// A owns slot 0, B owns slot 1, C owns slot 2
// Node A does a local write
A.clock = [2, 1, 0]  // A increments its own slot

// A sends a message to B, attaching [2, 1, 0]
// B currently holds [0, 3, 0]
B.clock = elementwiseMax([0, 3, 0], [2, 1, 0]) // -> [2, 3, 0]
B.clock[1] += 1 // B increments its own slot for the receive event
// B.clock is now [2, 4, 0]

