class VectorClock {
  constructor(nodeId, initial = {}) {
    this.nodeId = nodeId;
    this.counters = { ...initial }; // e.g. { A: 2, B: 1, C: 0 }
  }

  // Rule 1: bump your own slot on any local event
  tick() {
    this.counters[this.nodeId] = (this.counters[this.nodeId] || 0) + 1;
    return { ...this.counters };
  }

  // Rule 2: elementwise max on receipt, then tick your own slot
  merge(incoming) {
    const allNodes = new Set([...Object.keys(this.counters), ...Object.keys(incoming)]);
    for (const node of allNodes) {
      this.counters[node] = Math.max(this.counters[node] || 0, incoming[node] || 0);
    }
    this.tick();
    return { ...this.counters };
  }

  // Compare against another vector: 'before', 'after', 'equal' or 'concurrent'
  compareTo(other) {
    const allNodes = new Set([...Object.keys(this.counters), ...Object.keys(other)]);
    let selfSmallerSomewhere = false;
    let otherSmallerSomewhere = false;

    for (const node of allNodes) {
      const a = this.counters[node] || 0;
      const b = other[node] || 0;
      if (a < b) selfSmallerSomewhere = true;
      if (a > b) otherSmallerSomewhere = true;
    }

    if (!selfSmallerSomewhere && !otherSmallerSomewhere) return 'equal';
    if (selfSmallerSomewhere && !otherSmallerSomewhere) return 'before';
    if (!selfSmallerSomewhere && otherSmallerSomewhere) return 'after';
    return 'concurrent';
  }
}

// Usage
const a = new VectorClock('A');
a.tick(); // A: { A: 1 }
const b = new VectorClock('B');
b.tick(); // B: { B: 1 }

b.merge(a.counters); // B: { A: 1, B: 2 }
console.log(a.compareTo(b.counters)); // 'before'

